#!/usr/bin/env python3
"""
Comprehensive test of the Azure B2C client ID scope fix.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from msal.application import ClientApplication


# Mock authority to avoid network calls
class MockAuthority:
    def __init__(self, is_b2c=False):
        self._is_b2c = is_b2c
        self.is_adfs = False


# Test the _decorate_scope method directly
class TestClientApplication(ClientApplication):
    def __init__(self, client_id, is_b2c=False):
        # Skip the normal initialization to avoid network calls
        self.client_id = client_id
        self.authority = MockAuthority(is_b2c=is_b2c)
        self._exclude_scopes = set()


def test_b2c_scenarios():
    """Test Azure B2C scenarios that should now work"""
    print("=== Testing Azure B2C Scenarios ===\n")

    client_id = "test-client-id-12345"
    app = TestClientApplication(client_id=client_id, is_b2c=True)

    test_cases = [
        {
            "name": "Azure B2C documented pattern",
            "input": ["openid", "offline_access", client_id],
            "should_work": True
        },
        {
            "name": "B2C pattern with profile",
            "input": ["openid", "profile", "offline_access", client_id],
            "should_work": True
        },
        {
            "name": "Only client_id (should still work as before)",
            "input": [client_id],
            "should_work": True
        },
        {
            "name": "Custom scopes without client_id (should add reserved scopes)",
            "input": ["https://api.example.com/resource/.default"],
            "should_work": True
        }
    ]

    for case in test_cases:
        print(f"--- {case['name']} ---")
        print(f"Input: {case['input']}")
        try:
            result = app._decorate_scope(case['input'])
            print(f"Output: {sorted(result)}")  # Sort for consistent output
            if case['should_work']:
                print("✓ SUCCESS")
            else:
                print("? Unexpected success")
        except Exception as e:
            if case['should_work']:
                print(f"✗ UNEXPECTED ERROR: {e}")
            else:
                print(f"✓ Expected error: {e}")
        print()


def test_non_b2c_scenarios():
    """Test that non-B2C scenarios still work as before"""
    print("=== Testing Non-B2C Scenarios (Backward Compatibility) ===\n")

    client_id = "test-client-id-12345"
    app = TestClientApplication(client_id=client_id, is_b2c=False)

    test_cases = [
        {
            "name": "Only client_id (should be replaced with reserved scopes)",
            "input": [client_id],
            "should_work": True,
            "expected_contains": ["openid", "profile", "offline_access"],
            "expected_excludes": [client_id]  # client_id should be removed
        },
        {
            "name": "Custom scopes (should add reserved scopes)",
            "input": ["https://api.example.com/resource/.default"],
            "should_work": True
        },
        {
            "name": "Reserved scopes alone (should fail)",
            "input": ["openid"],
            "should_work": False
        },
        {
            "name": "Client ID mixed with others (should fail in non-B2C)",
            "input": ["openid", "offline_access", client_id],
            "should_work": False
        }
    ]

    for case in test_cases:
        print(f"--- {case['name']} ---")
        print(f"Input: {case['input']}")
        try:
            result = app._decorate_scope(case['input'])
            print(f"Output: {sorted(result)}")  # Sort for consistent output
            if case['should_work']:
                print("✓ SUCCESS")
                if 'expected_contains' in case:
                    result_set = set(result)
                    for expected in case['expected_contains']:
                        if expected in result_set:
                            print(f"  ✓ Contains expected '{expected}'")
                        else:
                            print(f"  ✗ Missing expected '{expected}'")
                if 'expected_excludes' in case:
                    result_set = set(result)
                    for not_expected in case['expected_excludes']:
                        if not_expected not in result_set:
                            print(f"  ✓ Correctly excludes '{not_expected}'")
                        else:
                            print(f"  ✗ Should not contain '{not_expected}'")
            else:
                print("? Unexpected success")
        except Exception as e:
            if case['should_work']:
                print(f"✗ UNEXPECTED ERROR: {e}")
            else:
                print(f"✓ Expected error: {e}")
        print()


def test_edge_cases():
    """Test edge cases"""
    print("=== Testing Edge Cases ===\n")

    client_id = "test-client-id-12345"

    # Test with B2C
    b2c_app = TestClientApplication(client_id=client_id, is_b2c=True)

    edge_cases = [
        {
            "name": "Empty scopes",
            "input": [],
            "app": b2c_app,
            "should_work": True
        },
        {
            "name": "Duplicate scopes",
            "input": ["openid", "openid", client_id],
            "app": b2c_app,
            "should_work": True
        }
    ]

    for case in edge_cases:
        print(f"--- {case['name']} ---")
        print(f"Input: {case['input']}")
        try:
            result = case['app']._decorate_scope(case['input'])
            print(f"Output: {sorted(result)}")
            if case['should_work']:
                print("✓ SUCCESS")
            else:
                print("? Unexpected success")
        except Exception as e:
            if case['should_work']:
                print(f"✗ UNEXPECTED ERROR: {e}")
            else:
                print(f"✓ Expected error: {e}")
        print()


if __name__ == "__main__":
    test_b2c_scenarios()
    test_non_b2c_scenarios()
    test_edge_cases()
